// @whimtex-brush Trails/Dynamic
// @param float _Period = 160 [1 .. 512]

float4 BrushTip(float2 uv, DynamicBrushContext brush)
{
    float radius = length(uv * 2.0 - 1.0);
    float coverage = 1.0 - smoothstep(0.75, 1.0, radius);
    float phase = brush.totalDistance / _Period;
    float perStroke = BrushRandom(brush.seed, brush.strokeIndex);
    float perStamp = BrushRandom(brush.seed, brush.strokeIndex, brush.stampIndex);
    float3 color = 0.5 + 0.5 * cos(6.2831853 * (phase + perStroke + float3(0, 0.33, 0.67)));
    return float4(color * lerp(0.8, 1.0, perStamp), coverage);
}
